function validate([strs]) {
  if (strs.length < 1 || strs.length > 1000) return 'strs needs 1 to 1000 strings.';
  if (strs.some(s => s.length < 1 || s.length > 1000)) return 'Each string has 1 to 1000 letters.';
  if (strs.reduce((sum, s) => sum + s.length, 0) > 1000) return 'All strings together have at most 1000 letters.';
  if (strs.some(s => !/^[a-z]+$/.test(s))) return 'Strings use lowercase English letters only.';
  return null;
}

