function splitLoopedString(strs) {
  const best = strs.map(s => {
    const reversed = s.split('').reverse().join('');
    return reversed > s ? reversed : s;
  });
  let answer = '';
  for (let i = 0; i < best.length; i++) {
    const rest = best.slice(i + 1).join('') + best.slice(0, i).join('');
    const flipped = best[i].split('').reverse().join('');
    for (const piece of [best[i], flipped]) {
      for (let cut = 0; cut < piece.length; cut++) {
        const candidate = piece.slice(cut) + rest + piece.slice(0, cut);
        if (candidate > answer) {
          answer = candidate;
        }
      }
    }
  }
  return answer;
}

