function splitLoopedString(strs) {
  // Try every combination of reversals and every rotation of the joined loop.
  const n = strs.length;
  let top = '';
  for (let mask = 0; mask < 1 << n; mask++) {
    let loop = '';
    for (let i = 0; i < n; i++) loop += mask & (1 << i) ? [...strs[i]].reverse().join('') : strs[i];
    for (let k = 0; k < loop.length; k++) {
      const rotated = loop.slice(k) + loop.slice(0, k);
      if (rotated > top) top = rotated;
    }
  }
  return top;
}

