function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, [2, 3, 26][pick(3)]);
  const word = length => Array.from({ length }, () => letters[pick(letters.length)]).join('');
  if (!large) {
    const n = 1 + pick(6);
    return [Array.from({ length: n }, () => word(1 + pick(4)))];
  }
  // Large: many short strings, a handful of long ones, or a mix, within 1000 letters in all.
  const shape = pick(3);
  const strs = [];
  let total = 0;
  for (;;) {
    const length = shape === 0 ? 1 + pick(4) : shape === 1 ? 50 + pick(250) : 1 + pick(60);
    if (total + length > 1000) break;
    strs.push(word(length));
    total += length;
  }
  if (strs.length === 0) strs.push(word(1000));
  return [strs];
}
